/* ==UserStyle==
@name           Sonar Cloud
@namespace      github.com/openstyles/stylus
@version        1.0.0
@description    User Style for SonarCloud
@author         Karthikeyan Vaithilingam
==/UserStyle== */

:root {
        --echoes-font-family-mono: var(--vknMonoFontFamily);
        --echoes-font-family-sans: var(--vknDefaultFontFamily);

        --echoes-typography-text-default-regular: 400 0.875rem/1.25rem var(--vknDefaultFontFamily);
        --echoes-typography-text-default-semi-bold: 600 0.875rem/1.25rem var(--vknDefaultFontFamily);
        --echoes-typography-text-default-bold: 700 0.875rem/1.25rem var(--vknDefaultFontFamily);
        --echoes-typography-text-small-medium: 500 0.75rem/1.125rem var(--vknDefaultFontFamily);
        --echoes-typography-text-small-semi-bold: 600 0.75rem/1.125rem var(--vknDefaultFontFamily);
        --echoes-typography-text-large-regular: 400 1rem/1.5rem var(--vknDefaultFontFamily);
        --echoes-typography-text-large-semi-bold: 600 1rem/1.5rem var(--vknDefaultFontFamily);
        --echoes-typography-heading-xsmall: 700 0.75rem/1.125rem var(--vknDefaultFontFamily);
        --echoes-typography-heading-small: 700 0.875rem/1.25rem var(--vknDefaultFontFamily);
        --echoes-typography-heading-medium: 600 1rem/1.5rem var(--vknDefaultFontFamily);
        --echoes-typography-heading-large: 600 1.25rem/1.875rem var(--vknDefaultFontFamily);
        --echoes-typography-heading-xlarge: 600 1.5rem/2.25rem var(--vknDefaultFontFamily);
        --echoes-typography-code-default: 400 0.875rem/1.25rem var(--vknMonoFontFamily);
        --echoes-typography-code-highlight: 700 0.875rem/1.25rem var(--vknMonoFontFamily);
        --echoes-typography-code-comment: 400 italic 0.875rem/1.25rem var(--vknMonoFontFamily);
        --echoes-typography-others-label: 600 0.875rem/1.25rem var(--vknDefaultFontFamily);
        --echoes-typography-others-label-medium: 500 0.875rem/1.25rem var(--vknDefaultFontFamily);
        --echoes-typography-others-helper-text: 500 0.75rem/1.125rem var(--vknDefaultFontFamily);
        --echoes-typography-display-default: 600 2.125rem/3.125rem var(--vknDefaultFontFamily);
    }

